package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TypedWakeTaskTest {
 static final String ENTRY="I dreamed about a quiet garden near the ocean and woke feeling calm and curious.";
 @Test public void mirrorPhraseIsStableForOneOccurrenceUnit(){assertEquals(MirrorText.phrase("run-a",2),MirrorText.phrase("run-a",2));}
 @Test public void newOccurrenceAndRoundProduceTheirOwnPhrase(){assertNotEquals(MirrorText.phrase("run-a",2),MirrorText.phrase("run-b",2));assertNotEquals(MirrorText.phrase("run-a",2),MirrorText.phrase("run-a",3));}
 @Test public void mirrorRequiresExactNormalPhraseIncludingDigits(){String phrase=MirrorText.phrase("run-a",0);assertTrue(MirrorText.accepts(phrase,phrase));assertFalse(MirrorText.accepts(phrase,new StringBuilder(phrase).reverse().toString()));assertFalse(MirrorText.accepts(phrase,phrase.toLowerCase(Locale.ROOT)));assertFalse(MirrorText.accepts(phrase,phrase.substring(0,phrase.length()-1)));}
 @Test public void missingOccurrenceCannotGenerateAValidTask(){assertThrows(IllegalArgumentException.class,()->MirrorText.phrase("",0));assertThrows(IllegalArgumentException.class,()->MirrorText.phrase("run",-1));}
 @Test public void actualJournalNeedsAllEngagementCriteria(){assertEquals("",JournalRule.problem(ENTRY,40));assertFalse(JournalRule.problem("a b c d e f g h",40).isEmpty());assertFalse(JournalRule.problem("morning ".repeat(20),40).isEmpty());assertFalse(JournalRule.problem("abcdefghijklmnopqrstuvwxyz abcdefghijklmnopqrstuvwxyz",40).isEmpty());}
 @Test public void configuredMinimumActuallyChangesAdmission(){assertEquals("",JournalRule.problem(ENTRY,40));assertFalse(JournalRule.problem(ENTRY,240).isEmpty());}
 @Test public void ArabicWordsAndUnicodeLettersCountWithoutEnglishDictionary(){assertEquals("",JournalRule.problem("رأيت حديقة جميلة قرب البحر وكانت السماء صافية وشعرت بالراحة والهدوء عندما استيقظت هذا الصباح",40));}
 @Test public void EmojiAndInvisibleCharactersCannotSatisfyLettersOrWords(){assertFalse(JournalRule.problem("🌞 ".repeat(100),40).isEmpty());assertFalse(JournalRule.problem("\u200b".repeat(100),40).isEmpty());}
 @Test public void overlongEntriesAndUnsupportedMinimumAreRejected(){assertFalse(JournalRule.problem(ENTRY.repeat(100),40).isEmpty());assertThrows(IllegalArgumentException.class,()->JournalRule.problem(ENTRY,41));}
 @Test public void journalIsExactlyOneUnitAndMirrorUsesConfiguredRounds(){ChallengeRoutine routine=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Mirror text",2),new ChallengeRoutine.Task("Dream journal",1)));assertEquals(3,routine.units());assertEquals("Dream journal",routine.at(2).task.type);assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Dream journal",2));}
 @Test public void staleDuplicateUnitCannotSkipJournalOrNextTask(){ChallengeRoutine routine=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Mirror text",1),new ChallengeRoutine.Task("Dream journal",1),new ChallengeRoutine.Task("Math",1)));assertEquals(1,routine.advance(0,0));assertEquals(1,routine.advance(1,0));assertEquals(2,routine.advance(1,1));assertEquals(2,routine.advance(2,1));}
 @Test public void unsupportedMinimumCannotAttachToOtherTasks(){assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Math",1,0,MathSettings.LEGACY,null,80));assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Dream journal",1,0,MathSettings.LEGACY,null,45));}
 @Test public void oldLegacyTaskGenerationAndOrderingRemainSupported(){for(String type:List.of("Math","Memory","Sequence","Retype","Shake","NFC")){ChallengeRoutine r=ChallengeRoutine.legacy(type,3);assertEquals(type,r.tasks.get(0).type);assertEquals(3,r.tasks.get(0).rounds);}assertEquals("Math",ChallengeRoutine.legacy("Dream journal",6).tasks.get(0).type);}
}
